// Normalize input from either Telegram or Lovable into one shape.
// Telegram sends: { message: { text, voice, chat: { id } } }
// Lovable sends: { source: 'lovable', user_id, text, audio_url }

const body = $input.first().json.body || $input.first().json;
let source, chatId, text, audioUrl;

if (body.message) {
  // Telegram update
  source = 'telegram';
  chatId = body.message.chat.id;
  text = body.message.text || null;
  audioUrl = body.message.voice ? `TELEGRAM_FILE:${body.message.voice.file_id}` : null;
} else {
  // Lovable web app
  source = 'lovable';
  chatId = body.user_id || 'lovable-default';
  text = body.text || null;
  audioUrl = body.audio_url || null;
}

return [{
  json: {
    source,
    chatId,
    text,
    audioUrl,
    raw: body,
    timestamp: new Date().toISOString()
  }
}];

// Merge transcribed text (if audio path) or pass through original text
const item = $input.first().json;
const transcript = item.text || ($json && $json.text) || '';
return [{ json: { ...item, finalText: transcript } }];

// Strip wake word 'Eric' if present, keep the command clean
const item = $input.first().json;
let cmd = (item.finalText || '').trim();
cmd = cmd.replace(/^(hey |ok |okay )?eric[,:]?\s*/i, '').trim();
return [{ json: { ...item, command: cmd } }];

// Build the routing prompt: combine command + any relevant past corrections
const item = $input.first().json;
const chroma = $input.first().json.documents ? $input.first().json : {};
let memoryNote = '';
try {
  const docs = (chroma.documents && chroma.documents[0]) || [];
  if (docs.length) {
    memoryNote = 'Relevant past corrections:\n' + docs.join('\n');
  }
} catch (e) {}

return [{ json: { ...item, memoryNote } }];

// Decide whether a device command is for the Windows laptop or the iPhone,
// and normalize it into an { device, action, params } shape.
const item = $input.first().json;
const cmd = item.command.toLowerCase();

let device, action, params = {};

if (/laptop|notepad|chrome|vscode|calculator|explorer|lock screen/.test(cmd)) {
  device = 'windows_laptop';
  if (/lock/.test(cmd)) { action = 'lock_screen'; }
  else if (/open/.test(cmd)) {
    action = 'open_app';
    const match = cmd.match(/open (notepad|chrome|vscode|calculator|explorer)/);
    params = { app: match ? match[1] : 'notepad' };
  } else { action = 'open_app'; params = { app: 'explorer' }; }
} else {
  device = 'iphone';
  if (/lights/.test(cmd)) { action = /off/.test(cmd) ? 'lights_off' : 'lights_on'; }
  else if (/lock the door/.test(cmd)) { action = 'lock_home'; }
  else if (/timer/.test(cmd)) { action = 'set_timer'; params = { duration: '10 minutes' }; }
  else if (/text/.test(cmd)) { action = 'send_text'; params = { message: cmd }; }
  else if (/maps/.test(cmd)) { action = 'open_maps'; }
  else { action = 'unknown'; }
}

return [{ json: { ...item, device, deviceAction: action, deviceParams: params } }];

// Push the command into a simple in-memory/DB queue that the
// Windows agent polls via GET /webhook/eric-device-commands.
// In production, back this with a tiny key-value store (n8n's own
// data store node, or a free Supabase table) keyed by device name.
const item = $input.first().json;
return [{ json: { ...item, queuedCommandId: 'cmd_' + Date.now() } }];

