// Parse the generated code into discrete files for storage
const item = $input.first().json;
const generated = Array.isArray(item) ? item[0].generated_text : (item.generated_text || item[0]?.generated_text || JSON.stringify(item));
const projectId = 'proj_' + Date.now();
return [{ json: { ...item, projectId, generatedCode: generated } }];

// Build a unified log entry for every single thing Eric does
const item = $input.first().json;
return [{ json: {
  logLine: `🤖 *Eric Log*\nSource: ${item.source}\nCommand: ${item.command || item.finalText}\nAction: ${item.actionTaken || 'processed'}\nStatus: ${item.status || 'ok'}\nTime: ${item.timestamp}`,
  chatId: item.chatId
} }];
